/bin/bash -lc "cat > /tmp/check-modal.cjs <<'JS'
const {chromium} = require('/home/node/.npm/_npx/420ff84f11983ee5/node_modules/playwright');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:5173');
  const trigger = page.getByRole('button', {name:'Открыть модальное окно'});
  await page.screenshot({path:'/tmp/modal-page.png',fullPage:true});
  await trigger.click();
  const dialog = page.getByRole('dialog');
  await dialog.waitFor({state:'visible'});
  await page.getByRole('button',{name:'Отменить',exact:true}).waitFor({state:'visible'});
  await page.screenshot({path:'/tmp/modal-open.png',fullPage:true});
  assert.equal(await page.getByRole('button',{name:'Отменить',exact:true}).evaluate(el => el===document.activeElement), true);
  await page.getByRole('button',{name:'Подтвердить',exact:true}).click();
  await dialog.waitFor({state:'hidden'});
  assert.match(await page.getByRole('status').innerText(), /успешно подтверждено/);
  await trigger.click();
  await page.getByRole('button',{name:'Отменить',exact:true}).click();
  await dialog.waitFor({state:'hidden'});
  assert.match(await page.getByRole('status').innerText(), /Действие отменено/);
  await trigger.click();
  await page.keyboard.press('Escape');
  await dialog.waitFor({state:'hidden'});
  assert.equal(await trigger.evaluate(el => el===document.activeElement), true);
  await page.setViewportSize({width:375,height:812});
  await trigger.click();
  await dialog.waitFor({state:'visible'});
  await page.screenshot({path:'/tmp/modal-mobile.png',fullPage:true});
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth),true);
  const confirmRect = await page.getByRole('button',{name:'Подтвердить',exact:true}).boundingBox();
  assert.ok(confirmRect.x + confirmRect.width <= 375);
  assert.deepEqual(errors, []);
  console.log('PASS: open, confirm, cancel, Escape, initial and restored focus, mobile layout, no runtime errors.');
  await browser.close();
})().catch(e => {console.error(e); process.exit(1)});
JS
